import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.Connection;
import java.util.List;

public class Check {
    static void show(String label, Document doc, String query) {
        FormElement form = (FormElement) doc.selectFirst(query);
        List<Connection.KeyVal> data = form.formData();
        StringBuilder sb = new StringBuilder();
        for (Connection.KeyVal kv : data) sb.append(kv.key()).append('=').append(kv.value()).append(' ');
        System.out.println(label + ": " + sb);
    }
    public static void main(String[] args) {
        // foster-parented controls: parser moves them out of the form; must appear once, in doc order
        show("foster", Jsoup.parse("<table><form><tr><td><input name=user value=u></td></tr><tr><td><input name=pass value=p></td></tr></form></table>"), "form");
        // mixed descendants + linked, interleaved
        show("mixed", Jsoup.parse("<form id=f><input name=a value=1><table><input name=b value=2></table><input name=c value=3></form>"), "form");
        // malformed: incomplete tags, dup names, dup selected, empty values
        show("malformed", Jsoup.parse("<form><input name=a><input name=a value><select name=s><option selected><option selected></select><input"), "form");
        // disabled nested + empty value
        show("disabled", Jsoup.parse("<form><fieldset disabled><input name=x value=1><legend><span><input name=y value=2></span></legend></fieldset></form>"), "form");
        // empty form
        show("empty", Jsoup.parse("<form></form>"), "form");
        // select with no options
        show("noopts", Jsoup.parse("<form><select name=s></select></form>"), "form");
        // external control before form, matching id; duplicate id where non-form element comes first
        show("extid", Jsoup.parse("<div id=g></div><input name=z value=9 form=g><form id=g><input name=a value=1></form>"), "form");
        // radio group: only checked submits; checkbox no value -> on
        show("checks", Jsoup.parse("<form><input type=radio name=r value=1><input type=radio name=r value=2 checked><input type=checkbox name=c checked></form>"), "form");
        // textarea + text inputs unchanged
        show("text", Jsoup.parse("<form><textarea name=t>hi there</textarea><input name=q value=abc></form>"), "form");
        // reassignment by reparenting into another form
        Document d = Jsoup.parse("<form id=f1><input name=m value=v></form><form id=f2></form>");
        Element input = d.selectFirst("input[name=m]");
        d.expectForm("#f2").appendChild(input);
        show("reparent-f1", d, "#f1");
        show("reparent-f2", d, "#f2");
        // detach control
        Document d2 = Jsoup.parse("<form><input name=m value=v></form>");
        d2.selectFirst("input").remove();
